package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.BufferRecycler;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.JsonFactory;
import com.fasterxml.jackson.core.io.JsonStreamContext;
import com.fasterxml.jackson.core.io.Name;
import com.fasterxml.jackson.core.sym.*;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class UTF8StreamJsonParser__releaseBuffers_TriageGen1Test {

    private IOContext mockIoContext;
    private Name mockSymbols;
    private Method releaseBuffersMethod;

    @Before
    public void setUp() throws Exception {
        mockIoContext = mock(IOContext.class);
        mockSymbols = mock(Name.class);

        // Accessing protected method via reflection
        releaseBuffersMethod = UTF8StreamJsonParser.class.getDeclaredMethod("_releaseBuffers");
        releaseBuffersMethod.setAccessible(true);
    }

    /**
     * Helper to instantiate the parser using the provided constructor and reflection to set private fields
     * to simulate the state required for testing.
     */
    private UTF8StreamJsonParser createParser(boolean bufferRecyclable, byte[] inputBuffer) throws Exception {
        InputStream in = new ByteArrayInputStream(new byte[]{1, 2, 3});
        // Constructor: public UTF8StreamJsonParser(IOContext ctxt, int features, InputStream in, ObjectCodec codec, BytesToNameCanonicalizer sym, byte[] inputBuffer, int start, int end, boolean bufferRecyclable);
        // Since we don't have a full mock for Sym, we pass null or a dummy.
        UTF8StreamJsonParser parser = new UTF8StreamJsonParser(
                mockIoContext, 
                0, 
                in, 
                null, 
                null, 
                inputBuffer, 
                0, 
                inputBuffer == null ? 0 : inputBuffer.length, 
                bufferRecyclable
        );

        // Inject mock symbols via reflection to verify _symbols.release()
        Field symbolsField = UTF8StreamJsonParser.class.getDeclaredField("_symbols");
        symbolsField.setAccessible(true);
        symbolsField.set(parser, mockSymbols);

        return parser;
    }

    @Test
    public void testReleaseBuffers_WithRecyclableBufferAndBufferPresent() throws Exception {
        byte[] buf = new byte[]{10, 20, 30};
        UTF8StreamJsonParser parser = createParser(true, buf);

        parser._releaseBuffers();

        // Verify symbols released
        verify(mockSymbols, times(1)).release();
        // Verify buffer returned to IOContext
        verify(mockIoContext, times(1)).releaseReadIOBuffer(buf);

        // Verify _inputBuffer is set to null via reflection
        Field inputBufferField = UTF8StreamJsonParser.class.getDeclaredField("_inputBuffer");
        inputBufferField.setAccessible(true);
        assert(inputBufferField.get(parser) == null);
    }

    @Test
    public void testReleaseBuffers_WithRecyclableBufferButNoBuffer() throws Exception {
        // Scenario: _bufferRecyclable is true, but _inputBuffer is null
        UTF8StreamJsonParser parser = createParser(true, null);

        parser._releaseBuffers();

        verify(mockSymbols, times(1)).release();
        // Should not call releaseReadIOBuffer if buf is null
        verify(mockIoContext, never()).releaseReadIOBuffer(any());
    }

    @Test
    public void testReleaseBuffers_WithoutRecyclableBuffer() throws Exception {
        byte[] buf = new byte[]{10, 20, 30};
        UTF8StreamJsonParser parser = createParser(false, buf);

        parser._releaseBuffers();

        verify(mockSymbols, times(1)).release();
        // Should NOT call releaseReadIOBuffer because _bufferRecyclable is false
        verify(mockIoContext, never()).releaseReadIOBuffer(any());

        // _inputBuffer should NOT be nullified
        Field inputBufferField = UTF8StreamJsonParser.class.getDeclaredField("_inputBuffer");
        inputBufferField.setAccessible(true);
        assert(inputBufferField.get(parser) != null);
    }
}
